window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s67-32","number":32,"surah":67,"verses":[10],"references":[{"surah":67,"verses":[10]}],"verseLabel":"الملك: 10","question":"ما أثر إحاطة حرف ﴿فِي﴾ بهم في قولهم ﴿مَا كُنَّا فِي أَصْحَابِ السَّعِيرِ﴾ بدل «من أصحاب السعير»؟","answer":"في تفيد الظرفية؛ فهم وقت هذا الاعتراف داخل السعير وفي عداد أصحابه معًا. أما «من أصحاب السعير» فتثبت الانتساب إليهم، لكنها لا تنص على أنهم واقعون فيها لحظة الكلام. فجاء الحرف مصورًا الإحاطة والعذاب الحاضر، لا مجرد الانتماء إلى الفريق.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: «ما دلالة استعمال في بدل من؟»، مبحث الآية (10).","url":""}]},{"id":"s67-33","number":33,"surah":67,"verses":[10],"references":[{"surah":67,"verses":[10]}],"verseLabel":"الملك: 10","question":"ما سر اقتران السمع بالعقل في اعتراف أهل السعير، وغياب البصر عن قولهم ﴿لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ﴾؟","answer":"المقام مقام نذير ورسالة تُلقى إليهم قولًا؛ فطريق تلقيها هو السمع، ثم يأتي العقل ليتدبر المسموع ويحكم بصدقه. وقد اعترفوا قبلها بأن النذير جاءهم فكذبوه، فناسب أن يذكروا الآلتين اللتين عطلوهما: سماع الوحي والاعتبار العقلي، لا مجرد الإبصار.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: «لماذا لم يقل لو كنا نبصر؟»، مبحث الآية (10).","url":""}]},{"id":"s67-34","number":34,"surah":67,"verses":[14],"references":[{"surah":67,"verses":[14]}],"verseLabel":"الملك: 14","question":"ما دلالة اختيار ﴿مَنْ﴾ في السؤال القاطع ﴿أَلَا يَعْلَمُ مَنْ خَلَقَ﴾؟","answer":"الأصل في من إذا انفردت أن تكون لذوات أولي العلم، بخلاف ما التي تستعمل لغير العاقل ولصفات أولي العلم. فجاءت من ملائمة للخالق العليم، ومركزةً السؤال على الذات المتصفة بالعلم والخلق، ثم أكد الختام هذا المعنى بقوله ﴿اللَّطِيفُ الْخَبِيرُ﴾.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: «الفرق بين ما ومن في الاستعمال اللغوي»، مبحث الآية (14).","url":""}]},{"id":"s67-35","number":35,"surah":67,"verses":[18],"references":[{"surah":67,"verses":[18]}],"verseLabel":"الملك: 18","question":"ما سر ختم التحذير بـ﴿فَكَيْفَ كَانَ نَكِيرِ﴾ لا «فكيف كان عقابي»؟","answer":"السورة تعرض مظاهر الرحمن ورحمته في تسخير الأرض والرزق وإمساك الطير؛ فجاء نكير، أي إنكار الله عليهم وتغييره حالهم بالعقوبة، أنسب بخيط السورة اللفظي. أما موضع الرعد الذي غلب عليه الأخذ والجزاء فخُتم بـ﴿فَكَيْفَ كَانَ عِقَابِ﴾، فناسب كل ختام سياقه.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «الفرق بين الرحمن وصافات في الملك، والله ومسخرات في النحل»، المبحث المتصل بالآيات (15–21).","url":""}]},{"id":"s67-36","number":36,"surah":67,"verses":[23],"references":[{"surah":67,"verses":[23]}],"verseLabel":"الملك: 23","question":"ما دلالة الجزم بقلة الشكر ﴿قَلِيلًا مَا تَشْكُرُونَ﴾، في مقابل ﴿لَعَلَّكُمْ تَشْكُرُونَ﴾ في سورة النحل؟","answer":"آية النحل تذكر النعم وغايتها، فجاء الرجاء ﴿لَعَلَّكُمْ تَشْكُرُونَ﴾ دعوةً إلى تحقيق الشكر. أما سورة الملك فتخاطب قومًا قائمين في العتو والنفور، ينكرون الوعد ويعرضون عن دلائل القدرة؛ فناسب مقامُ الحكم على واقعهم التقريرَ بأن شكرهم قليل.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «لعلكم تشكرون وقليلًا ما تشكرون»، المبحث المتصل بالآية (23).","url":""}]},{"id":"s67-37","number":37,"surah":67,"verses":[25],"references":[{"surah":67,"verses":[25]}],"verseLabel":"الملك: 25","question":"ما دلالة المضارع في ﴿وَيَقُولُونَ مَتَى هَذَا الْوَعْدُ﴾ بدل أن يقال «وقالوا»؟","answer":"المضارع يصور القول متجددًا مستمرًا، فهم لم يلقوا السؤال مرة ثم سكتوا، بل ظلوا يكررونه استهزاءً وإنكارًا كلما أُنذروا بالآخرة. وبهذا تحولت العبارة من نقل مقولة ماضية إلى مشهد حي يكشف إصرارهم المتواصل.","sources":[{"label":"فاضل السامرائي، منصة باحث: «ويقولون متى هذا الوعد إن كنتم صادقين».","url":""}]},{"id":"s67-38","number":38,"surah":67,"verses":[27],"references":[{"surah":67,"verses":[27]}],"verseLabel":"الملك: 27","question":"ما سر اختيار ﴿زُلْفَةً﴾ لحظة انكشاف الوعد الذي طالما استبعده الكافرون؟","answer":"الزلفة هي القرب، وفي مادتها إيحاء بالتقرب والدنو؛ فإذا باليوم الذي جعلوه بعيدًا حاضر قريب أمام وجوههم. وجاء ﴿سِيئَتْ وُجُوهُ﴾ مبنيًا للمجهول لأن سبب الإساءة مشاهد معلوم، ولتركيز الصورة على أثر المفاجأة البادي في الوجوه.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «ما معنى فلما رأوه زلفة سيئت وجوه الذين كفروا؟»، مبحث الآية (27).","url":""}]},{"id":"s67-39","number":39,"surah":67,"verses":[29],"references":[{"surah":67,"verses":[29]}],"verseLabel":"الملك: 29","question":"ما دلالة تأخير ﴿بِهِ﴾ في ﴿آمَنَّا بِهِ﴾، وتقديم ﴿عَلَيْهِ﴾ في ﴿وَعَلَيْهِ تَوَكَّلْنَا﴾؟","answer":"الإيمان لا ينحصر في الإيمان بالله وحده؛ بل يشمل ملائكته وكتبه ورسله واليوم الآخر، فلم يُقدَّم الجار والمجرور على وجه الحصر. أما التوكل فلا يكون إلا على الله، فقُدِّم ﴿عَلَيْهِ﴾ لإفادة الاختصاص: عليه وحده اعتمدنا، إذ لا يملك غيره ضرًا ولا نفعًا.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «دلالة تقديم وتأخير الجار والمجرور في آمنا به وعليه توكلنا»، مبحث الآية (29).","url":""}]},{"id":"s67-40","number":40,"surah":67,"verses":[30],"references":[{"surah":67,"verses":[30]}],"verseLabel":"الملك: 30","question":"ما الأثر البلاغي لاختتام السورة بسؤال الماء: ﴿فَمَنْ يَأْتِيكُمْ بِمَاءٍ مَعِينٍ﴾؟","answer":"هو استفهام تقريري يلزم المخاطَب بالإقرار بأن المنعم الأول واحد، وأن أحدًا لا يستطيع رد الماء إذا غار. وهو خاتمة لسلسلة من الأسئلة: من ينصركم؟ من يرزقكم؟ من يجير الكافرين؟ ثم تُختم بأقرب ضرورة للحياة، فيعود آخر السورة إلى معنى أولها: الملك والقدرة له وحده.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «ما دلالة هذا السؤال في ختام سورة الملك؟»، مبحث الآية (30).","url":""}]},{"id":"s68-43","number":43,"surah":68,"verses":[2,51],"references":[{"surah":68,"verses":[2,51]}],"verseLabel":"القلم: 2، 51","question":"كيف ردَّ مطلع السورة على تهمة الجنون في ختامها بأداة توكيد تماثل توكيدهم؟","answer":"قال المكذبون في الختام ﴿إِنَّهُ لَمَجْنُونٌ﴾ فأكدوا دعواهم باللام، وجاء الرد في المطلع ﴿مَا أَنْتَ… بِمَجْنُونٍ﴾ بالباء المؤكدة للنفي. فواجه التوكيدَ في الإثبات توكيدٌ في النفي، وربط آخر السورة بأولها ربطًا محكمًا.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ج1، ص169، مبحث مناسبة خاتمة القلم لمطلعها. النص المباشر.","url":""}]},{"id":"s68-44","number":44,"surah":68,"verses":[7],"references":[{"surah":68,"verses":[7]}],"verseLabel":"القلم: 7","question":"ما دلالة الماضي في ﴿أَعْلَمُ بِمَنْ ضَلَّ عَنْ سَبِيلِهِ﴾، في مقابل المضارع ﴿مَنْ يَضِلُّ﴾ في الأنعام؟","answer":"سياق الأنعام شرطٌ متعلق بالمستقبل: إن تطع أكثر من في الأرض يضلوك؛ فناسبه المضارع ﴿مَنْ يَضِلُّ﴾. أما القلم فتعرض أشخاصًا استقر ضلالهم وظهرت صفاتهم: المكذب والحلاف والهماز والمشاء بنميم؛ فناسب الماضي ﴿مَنْ ضَلَّ﴾.","sources":[{"label":"فاضل السامرائي، منصة باحث: «الفرق بين إن ربك هو أعلم من يضل… وأعلم بمن ضل».","url":""}]},{"id":"s68-45","number":45,"surah":68,"verses":[10,14],"references":[{"surah":68,"verses":[10,14]}],"verseLabel":"القلم: 10، 14","question":"ما سر تعقيب الصفات الذميمة بقوله ﴿أَنْ كَانَ ذَا مَالٍ وَبَنِينَ﴾؟","answer":"المال والبنون موضع قوة ومنعة في المجتمع، وقد يحملان الناس على الخضوع لصاحبهما مع فساد خلقه. فجاء التعقيب كاشفًا سبب اغتراره واستعلائه، ومحذرًا من طاعته لأجل جاهه؛ فلا يحوّل المال والبنون الحلافَ المهين والهمازَ المعتدي إلى صاحب أهلية للاتباع.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: مبحث «همّاز مشاء بنميم» وعلاقة المال والبنين بالنهي عن الطاعة.","url":""}]},{"id":"s68-46","number":46,"surah":68,"verses":[11],"references":[{"surah":68,"verses":[11]}],"verseLabel":"القلم: 11","question":"ما سر وصفه بـ﴿هَمَّازٍ﴾، بينما جاء في السورة الأخرى ﴿هُمَزَةٍ﴾؟","answer":"همّاز على وزن فعّال، وهي صيغة تشعر بالمزاولة والحرفة؛ فكأن الهمز صار عادةً يتعامل بها مع الناس. أما هُمزة فالمبالغة فيها بالتاء تبلغ نهاية الوصف، وناسبت سورة الهمزة التي فصّلت النهاية والعاقبة في الحطمة. وسورة القلم ركزت على السلوك المتكرر الذي يمنع طاعة صاحبه.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «ما الفرق بين هُمَزة وهمّاز؟»، مبحث الآية (11).","url":""}]},{"id":"s68-47","number":47,"surah":68,"verses":[12],"references":[{"surah":68,"verses":[12]}],"verseLabel":"القلم: 12","question":"ما دلالة صيغة ﴿أَثِيمٍ﴾ بدل «آثم» وسط هذا السيل من الصفات؟","answer":"أثيم أبلغ من آثم، وقد سبقها في الوصف حلاف وهمّاز ومشّاء ومنّاع ومعتدٍ؛ وكلها تدل على التكرار والمبالغة. ومن اجتمعت فيه هذه الخصال لا يوصف بمجرد وقوع الإثم منه، بل بكثرته ورسوخه فيه، فجاءت الصيغة موافقة لجو المبالغة في السياق.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «ما الفرق بين أثيم وآثم؟»، مبحث الآية (12).","url":""}]},{"id":"s69-46","number":46,"surah":69,"verses":[4],"references":[{"surah":69,"verses":[4]}],"verseLabel":"الحاقة: 4","question":"ما دلالة تقديم ثمود على عاد هنا، مع أن عادًا أسبق زمنًا؟","answer":"السمت العام في السورة الانتقال من الأقرب إلى الأبعد: ثمود ثم عاد، وفرعون ثم من قبله، ثم قوم نوح. ويمتد النسق إلى مشاهد القيامة، فتذكر الأرض والجبال قبل السماء، وإلى القسم بما نبصر قبل ما لا نبصر؛ فكان التقديم جزءًا من نظام السورة لا مجرد ترتيب تاريخي.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «دلالة تقديم ثمود على عاد»، مبحث الآية (4).","url":""}]},{"id":"s69-47","number":47,"surah":69,"verses":[13],"references":[{"surah":69,"verses":[13]}],"verseLabel":"الحاقة: 13","question":"ما سر تذكير الفعل في ﴿نُفِخَ فِي الصُّورِ نَفْخَةٌ﴾ مع أن «نفخة» مؤنثة؟","answer":"«نفخة» مؤنث مجازي يجوز معه التذكير، وقد فصل الجار والمجرور بين الفعل ونائب الفاعل فحسّن التذكير. وجاءت قراءة بالنصب تجعل «نفخةً» مفعولًا مطلقًا لا فاعلًا أصلًا. وفوق ذلك، فإن المقام مقام شدة وهول، والتذكير يُختار في نظائر القرآن للمقام الأشد.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «لماذا جاء الفعل نفخ مذكرًا؟»، مبحث الآية (13).","url":""}]},{"id":"s69-48","number":48,"surah":69,"verses":[13,14],"references":[{"surah":69,"verses":[13,14]}],"verseLabel":"الحاقة: 13، 14","question":"ما سر رفع ﴿نَفْخَةٌ﴾ ونصب ﴿دَكَّةً﴾ في مشهدين متتابعين؟","answer":"﴿نَفْخَةٌ﴾ نائب فاعل للفعل المبني للمجهول ﴿نُفِخَ﴾، ولذلك رُفعت. أما في ﴿فَدُكَّتَا دَكَّةً﴾ فنائب الفاعل هو ألف التثنية العائدة إلى الأرض والجبال، وجاءت ﴿دَكَّةً﴾ مفعولًا مطلقًا يبين نوع الدك ويوكده؛ فاختلاف الحركة تابع لاختلاف البنية والمعنى.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «لماذا نفخة مرفوعة ودكة منصوبة؟»، مبحث الآيتين (13–14).","url":""}]},{"id":"s69-49","number":49,"surah":69,"verses":[37],"references":[{"surah":69,"verses":[37]}],"verseLabel":"الحاقة: 37","question":"ما دلالة ﴿الْخَاطِئُونَ﴾، وما الفرق بينها وبين «المخطئون»؟","answer":"الخاطئ من خَطِئَ، أي ارتكب الخطيئة عن تعمد، أما المخطئ فمن أخطأ، وهو من لم يتعمد الصواب أو وقع منه الخطأ. وطعام الغسلين ليس لمن وقع في هفوة عارضة، بل لمن رسخ في الخطيئة المتعمدة، فجاء الوصف مشددًا لمسؤوليته.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «الفرق بين الخاطئ والمخطئ»، مبحث الآية (37).","url":""}]},{"id":"s69-50","number":50,"surah":69,"verses":[38],"references":[{"surah":69,"verses":[38]}],"verseLabel":"الحاقة: 38","question":"ما دلالة ﴿فَلَا أُقْسِمُ﴾؛ أهو نفي للقسم أم زيادة في توكيده؟","answer":"لم يرد فعل ﴿أُقْسِمُ﴾ في القرآن إلا مسبوقًا بـ«لا». وقيل إنها زائدة لتوكيد القسم، وقيل نافية على أسلوب التعظيم: الأمر أوضح وأعظم من أن يحتاج إلى قسم، ثم يأتي القسم توكيدًا له. وعلى الوجهين لا تلغي «لا» القسم، بل تزيده قوةً وتعظيمًا.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «هل هو قسم وما معنى وجود لا؟»، ومن شواهده ﴿فلا أقسم بما تبصرون﴾.","url":""}]},{"id":"s69-51","number":51,"surah":69,"verses":[49,52],"references":[{"surah":69,"verses":[49,52]}],"verseLabel":"الحاقة: 49، 52","question":"كيف يعيد ختام الحاقة قارئها إلى افتتاحها، ثم يحوّل الحسرة إلى تسبيح؟","answer":"بدأت السورة بالمكذبين بالحاقة وعاقبة ثمود وعاد، وختمت بأن في المخاطبين مكذبين وأن القرآن حسرة على الكافرين؛ فالتكذيب في الطرفين وعاقبته بينهما. ثم ثبت أنه حق اليقين، فجيء بالأمر بالتسبيح تنزيهًا لله وتعظيمًا لرب العالمين الذي أنزل هذا الحق وأخبر بالحاقة.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «تناسب فواتح سورة الحاقة مع خواتيمها»، مبحث الآية (52).","url":""}]},{"id":"s69-52","number":52,"surah":69,"verses":[51],"references":[{"surah":69,"verses":[51]}],"verseLabel":"الحاقة: 51","question":"ما منزلة ﴿حَقُّ الْيَقِينِ﴾ بين علم اليقين وعين اليقين؟","answer":"علم اليقين هو ثبوت الخبر في العلم دون شك، وعين اليقين أن يُشاهد المعلوم، وحق اليقين أن يُباشَر ويُذاق وتتحقق حقيقته. فمعرفة الناس بالموت علم يقين، ورؤية ملائكته عند النزع عين يقين، ووقوع الموت ومباشرته حق اليقين؛ ولذلك كانت هذه المرتبة أعلاها.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «الفرق بين علم اليقين وعين اليقين وحق اليقين»، مبحث الآية (51).","url":""}]},{"id":"s70-45","number":45,"surah":70,"verses":[9],"references":[{"surah":70,"verses":[9]}],"verseLabel":"المعارج: 9","question":"ما سر الاقتصار في سورة المعارج على قوله تعالى: ﴿وَتَكُونُ الْجِبَالُ كَالْعِهْنِ﴾، وزيادة كلمة ﴿الْمَنْفُوشِ﴾ في سورة القارعة؟","answer":"سورة القارعة مبنية على القرع والتكرار والتهويل، ومن معاني القرع نفش الصوف، كما أن الجبال تُهشّم بالمِقراع. لذلك ناسب سياق القارعة وصف الجبال بالعهن المنفوش. أما في المعارج فالسياق أكثر إجمالًا، وجاء ذكر السماء كالمهل، فناسبه الاقتصار على «العهن».","sources":[{"label":"فاضل السامرائي، «من سورتي المعارج والقارعة»، لمسات بيانية في نصوص من التنزيل، ج1، ص197–200، عنوان المبحث: «من سورتي المعارج والقارعة»،","url":""}]},{"id":"s70-46","number":46,"surah":70,"verses":[11,14],"references":[{"surah":70,"verses":[11,14]}],"verseLabel":"المعارج: 11، 14","question":"ما سر تقديم الأبناء في قوله تعالى: ﴿بِبَنِيهِ * وَصَاحِبَتِهِ وَأَخِيهِ﴾؟","answer":"المقام مقام عذاب لا يُطاق، والمجرم يريد أن يفتدي نفسه بأي شيء، ولو بدأ بأقرب الناس إلى قلبه وأشدهم تعلقًا به. لذلك بدأ بالأبناء، ثم الزوجة، ثم الأخ، ثم الفصيلة، ثم عمّم فقال: ﴿وَمَن فِي الْأَرْضِ جَمِيعًا﴾. أما في سورة عبس فالمقام مقام فرار، فناسب أن يبدأ بالأبعد ثم ينتهي إلى الأقرب.","sources":[{"label":"فاضل السامرائي، «من سورتي المعارج وعبس»، لمسات بيانية في نصوص من التنزيل، ج1، ص193–196، س","url":""}]},{"id":"s70-47","number":47,"surah":70,"verses":[43],"references":[{"surah":70,"verses":[43]}],"verseLabel":"المعارج: 43","question":"ما دلالة اختيار لفظ ﴿الْأَجْدَاثِ﴾ بدل «القبور» في قوله تعالى: ﴿يَخْرُجُونَ مِنَ الْأَجْدَاثِ﴾؟","answer":"«الأجداث» جمع «جدث»، وهو القبر، واختيار هذه الكلمة ينسجم مع مشهد الخروج السريع المضطرب. وقد ربط الدكتور السامرائي اللفظ بجو الحركة والاضطراب في الآية، بخلاف لفظ «القبور» الذي يركز على موضع الدفن دون الإيحاء الحركي نفسه.","sources":[{"label":"فاضل السامرائي، مادة إلكترونية، «الفرق بين استخدام الأجداث والقبور»، https://tadars.com/source/442?page=132","url":""}]},{"id":"s72-50","number":50,"surah":72,"verses":[2],"references":[{"surah":72,"verses":[2]}],"verseLabel":"الجن: 2","question":"لماذا قال هنا: ﴿يَهْدِي إِلَى الرُّشْدِ﴾، وقال في الأحقاف: ﴿يَهْدِي إِلَى الْحَقِّ﴾؟","answer":"الحق أعم من الرشد، وقد اتسع الحديث عن القرآن في الأحقاف، فذكر سماع الجن له ورجوعهم إلى قومهم منذرين ودعوتهم إلى الإيمان. فناسب السياق الأوسع لفظ «الحق»، وناسب الإيجاز هنا لفظ «الرشد».","sources":[{"label":"https://islamiyyat.com/لمسات-بيانية-الحلقة-109/","url":""}]},{"id":"s72-51","number":51,"surah":72,"verses":[10],"references":[{"surah":72,"verses":[10]}],"verseLabel":"الجن: 10","question":"لماذا بُني الفعل للمجهول في ﴿أَشَرٌّ أُرِيدَ بِمَنْ فِي الْأَرْضِ﴾، وأُسند إلى الرب في ﴿أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَدًا﴾؟","answer":"بُني الفعل للمجهول عند ذكر الشر، وأُسندت إرادة الرشد إلى الرب؛ تأدبًا في التعبير، بإسناد الخير إليه وعدم التصريح بإسناد الشر في هذا الموضع.","sources":[{"label":"السامرائي، لمسات بيانية في نصوص من التنزيل، ص65.","url":""}]},{"id":"s72-52","number":52,"surah":72,"verses":[10],"references":[{"surah":72,"verses":[10]}],"verseLabel":"الجن: 10","question":"ما مناسبة ذكر «ربهم» في قوله: ﴿أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَدًا﴾؟","answer":"الرب هو المربي والقائم على الأمر والرازق والهادي، فناسب ذكره عند إرادة الرشد والصلاح لهم.","sources":[{"label":"https://islamiyyat.com/لمسات-بيانية-الحلقة-115/","url":""}]},{"id":"s72-53","number":53,"surah":72,"verses":[25],"references":[{"surah":72,"verses":[25]}],"verseLabel":"الجن: 25","question":"لماذا قال: ﴿أَقَرِيبٌ مَا تُوعَدُونَ أَمْ يَجْعَلُ لَهُ رَبِّي أَمَدًا﴾، ولم يقابل القريب بالبعيد؟","answer":"الأمد هو الغاية، وقد يكون قريبًا أو بعيدًا. وهذا جارٍ على نمط ظاهر في السورة، إذ يُذكر الشيء ويُذكر معه ما يتضمن مقابله، دون الاقتصار على المقابل المباشر.","sources":[{"label":"https://islamiyyat.com/الجن/","url":""}]},{"id":"s73-25","number":25,"surah":73,"verses":[8],"references":[{"surah":73,"verses":[8]}],"verseLabel":"المزمل: 8","question":"ما مناسبة التعبير عن التدرج بالفعل ﴿تَبَتَّلْ﴾، وعن الكثرة بالمصدر ﴿تَبْتِيلًا﴾؟","answer":"الفعل يدل على التجدد والحدوث، فناسب التدرج، لأنه مرحلة يُنتقل منها. والمصدر اسم يدل على الثبوت والمبالغة، فناسب الكثرة التي يُراد الاستقرار عليها في العبادة.","sources":[{"label":"السامرائي، معاني النحو، ج2، ص163.","url":""}]},{"id":"s73-26","number":26,"surah":73,"verses":[15,16],"references":[{"surah":73,"verses":[15,16]}],"verseLabel":"المزمل: 15، 16","question":"لماذا نُكِّر الرسول في ﴿كَمَا أَرْسَلْنَا إِلَى فِرْعَوْنَ رَسُولًا﴾، ثم عُرِّف في ﴿فَعَصَى فِرْعَوْنُ الرَّسُولَ﴾؟","answer":"«أل» للعهد الذكري؛ لتدل على أن الرسول الذي عصاه فرعون هو نفسه المذكور قبلها. ولو أُعيد نكرة لتُوهِّم أنه رسول آخر.","sources":[{"label":"السامرائي، معاني النحو، ج1، ص114.","url":""}]},{"id":"s73-27","number":27,"surah":73,"verses":[20],"references":[{"surah":73,"verses":[20]}],"verseLabel":"المزمل: 20","question":"لماذا زاد هنا: ﴿هُوَ خَيْرًا وَأَعْظَمَ أَجْرًا﴾، بينما قال في البقرة: ﴿تَجِدُوهُ عِنْدَ اللَّهِ﴾ دون هذه الزيادة؟","answer":"لأنه زاد هنا على إقامة الصلاة وإيتاء الزكاة قراءة القرآن والقرض الحسن، فناسبت زيادةُ أعمال الخير زيادةَ الخير وعِظَم الأجر في الجزاء.","sources":[{"label":"السامرائي، مراعاة المقام في التعبير القرآني، ص11.","url":""}]},{"id":"s73-28","number":28,"surah":73,"verses":[20],"references":[{"surah":73,"verses":[20]}],"verseLabel":"المزمل: 20","question":"ما مناسبة قوله في ختام السورة: ﴿إِنَّ رَبَّكَ يَعْلَمُ أَنَّكَ تَقُومُ أَدْنَى مِنْ ثُلُثَيِ اللَّيْلِ وَنِصْفَهُ وَثُلُثَهُ﴾ لافتتاحها؟","answer":"بدأت السورة بالأمر بقيام الليل، وجاء ختامها ببيان الاستجابة لذلك الأمر. وأمرت أولًا بترتيل القرآن، ثم جاء في ختامها التيسير للمؤمنين بقراءة ما تيسر منه.","sources":[{"label":"https://islamiyyat.com/المزمل/","url":""}]},{"id":"s74-51","number":51,"surah":74,"verses":[33,34],"references":[{"surah":74,"verses":[33,34]}],"verseLabel":"المدثر: 33، 34","question":"لماذا قال: ﴿وَاللَّيْلِ إِذْ أَدْبَرَ﴾، و﴿وَالصُّبْحِ إِذَا أَسْفَرَ﴾؟","answer":"«إذ» للماضي غالبًا، و«إذا» للمستقبل؛ فذُكر الليل باعتبار إدباره وانقضائه، والصبح باعتبار إسفاره الآتي.","sources":[{"label":"https://islamiyyat.com/المدثر/","url":""}]},{"id":"s74-52","number":52,"surah":74,"verses":[35],"references":[{"surah":74,"verses":[35]}],"verseLabel":"المدثر: 35","question":"ماذا أفاد قوله: ﴿إِنَّهَا لَإِحْدَى الْكُبَرِ﴾؟","answer":"«الكُبَر» جمع «الكبرى»، مؤنث «الأكبر». فسقر واحدة من عظائم البلايا، وليست العبارة حصرًا لجميع العظائم فيها.","sources":[{"label":"https://islamiyyat.com/المدثر/","url":""}]},{"id":"s74-53","number":53,"surah":74,"verses":[43,44],"references":[{"surah":74,"verses":[43,44]}],"verseLabel":"المدثر: 43، 44","question":"ما مناسبة حذف النون في ﴿لَمْ نَكُ مِنَ الْمُصَلِّينَ وَلَمْ نَكُ نُطْعِمُ الْمِسْكِينَ﴾؟","answer":"قد يشير الحذف إلى عجز المتكلم عن إتمام الكلام لما به من ضعف وإرهاق، أو إلى عزوفه عن الحديث؛ فيوجز ما استطاع. وهذا من الأوجه المحتملة في كلام أهل النار.","sources":[{"label":"السامرائي، معاني النحو، ج1، ص232.","url":""}]},{"id":"s75-33","number":33,"surah":75,"verses":[4],"references":[{"surah":75,"verses":[4]}],"verseLabel":"القيامة: 4","question":"ما مناسبة تخصيص البنان في ﴿بَلَى قَادِرِينَ عَلَى أَنْ نُسَوِّيَ بَنَانَهُ﴾، وإطلاق التسوية في ﴿فَخَلَقَ فَسَوَّى﴾؟","answer":"تسوية البنان مرتبطة بذكر جمع العظام، والبنان عظام، فناسب التخصيص. أما ﴿فَخَلَقَ فَسَوَّى﴾ فمرتبطة بالخلق العام للإنسان، فناسبها إطلاق التسوية.","sources":[{"label":"السامرائي، لمسات بيانية في نصوص من التنزيل، ص205.","url":""}]},{"id":"s75-34","number":34,"surah":75,"verses":[12],"references":[{"surah":75,"verses":[12]}],"verseLabel":"القيامة: 12","question":"ما الذي تحتمله كلمة ﴿الْمُسْتَقَرُّ﴾ في قوله: ﴿إِلَى رَبِّكَ يَوْمَئِذٍ الْمُسْتَقَرُّ﴾؟","answer":"تحتمل الاستقرار وموضعه؛ فاستقرار العباد إلى حكمه، وموضع قرارهم من جنة أو نار إلى مشيئته. وقد ورد بيان هذين الوجهين في النقل عن «الكشاف» و«البحر المحيط».","sources":[{"label":"السامرائي، لمسات بيانية في نصوص من التنزيل، ص210.","url":""}]},{"id":"s75-35","number":35,"surah":75,"verses":[16],"references":[{"surah":75,"verses":[16]}],"verseLabel":"القيامة: 16","question":"ما مناسبة ﴿لَا تُحَرِّكْ بِهِ لِسَانَكَ لِتَعْجَلَ بِهِ﴾ لما قبلها ولجو السورة؟","answer":"العجلة من أسباب لوم النفس بعد الفعل، وقد افتتحت السورة بالنفس اللوامة، وسبق ذكر النفس في ﴿بَلِ الْإِنْسَانُ عَلَى نَفْسِهِ بَصِيرَةٌ﴾؛ فذكر العجلة متصل بهذا المعنى.","sources":[{"label":"السامرائي، لمسات بيانية في نصوص من التنزيل، ص202.","url":""}]},{"id":"s75-36","number":36,"surah":75,"verses":[26,27],"references":[{"surah":75,"verses":[26,27]}],"verseLabel":"القيامة: 26، 27","question":"ما مناسبة الإبهام في ﴿إِذَا بَلَغَتِ التَّرَاقِيَ وَقِيلَ مَنْ رَاقٍ﴾؟","answer":"لم يُصرَّح بالنفس التي بلغت التراقي، ولم يُعيَّن القائل. و«راقٍ» تحتمل من يرقيه طلبًا لشفائه، ومن يرقى بروحه؛ فاجتمع الحذف والإبهام بما يلائم جو العجلة في السورة.","sources":[{"label":"السامرائي، لمسات بيانية في نصوص من التنزيل، ص221–222.","url":""}]},{"id":"s76-42","number":42,"surah":76,"verses":[2],"references":[{"surah":76,"verses":[2]}],"verseLabel":"الإنسان: 2","question":"لماذا قال هنا: ﴿نَبْتَلِيهِ﴾، وقال في الملك: ﴿لِيَبْلُوَكُمْ﴾؟","answer":"«نبتليه» أشد في الاختبار، وقد فصّل هنا وسائل الابتلاء وأعمال المؤمنين والكافرين. أما في الملك فخفف في الصيغة، وناسب ذلك قوله: ﴿وَهُوَ الْعَزِيزُ الْغَفُورُ﴾.","sources":[{"label":"https://tadars.com/tdbr/eloquence/12253","url":""}]},{"id":"s76-43","number":43,"surah":76,"verses":[3],"references":[{"surah":76,"verses":[3]}],"verseLabel":"الإنسان: 3","question":"لماذا قال: ﴿إِمَّا شَاكِرًا وَإِمَّا كَفُورًا﴾، فاستعمل اسم الفاعل في الأول والمبالغة في الثاني؟","answer":"لأن الإنسان يبالغ في الكفران، أما المبالغون في الشكر فقليلون. ولو قال «شكورًا» لأخرج الشاكرين الذين لم يبلغوا المبالغة. وقد نُقل نحو هذا عن «البحر المحيط».","sources":[{"label":"https://tadars.com/tdbr/eloquence/12254","url":""}]},{"id":"s76-44","number":44,"surah":76,"verses":[3],"references":[{"surah":76,"verses":[3]}],"verseLabel":"الإنسان: 3","question":"لماذا قال: ﴿هَدَيْنَاهُ السَّبِيلَ﴾ دون «هديناه إلى السبيل»؟","answer":"التعدية المباشرة تشمل من كان في السبيل ومن لم يكن فيه، أما التعدية بـ«إلى» فتقال لمن لم يكن فيه؛ فجمع التعبير الإيصال إلى السبيل والتعريف به.","sources":[{"label":"https://tadars.com/tdbr/eloquence/12254","url":""}]},{"id":"s76-45","number":45,"surah":76,"verses":[4],"references":[{"surah":76,"verses":[4]}],"verseLabel":"الإنسان: 4","question":"لماذا قال: ﴿لِلْكَافِرِينَ﴾ بعد قوله: ﴿وَإِمَّا كَفُورًا﴾، ولم يجمع «كفورًا»؟","answer":"ليشمل الوعيد من بالغ في الكفر ومن لم يبالغ فيه؛ فذكر الكافر يدخل فيه الكفور من باب أولى، ولا يوهم اختصاص الوعيد بالمبالغين.","sources":[{"label":"السامرائي، على طريق التفسير البياني، ج1، ص221–224.","url":""}]},{"id":"s76-46","number":46,"surah":76,"verses":[5],"references":[{"surah":76,"verses":[5]}],"verseLabel":"الإنسان: 5","question":"لماذا قال: ﴿إِنَّ الْأَبْرَارَ﴾، ووصف الملائكة في عبس بـ﴿بَرَرَةٍ﴾؟","answer":"«الأبرار» جمع قلة يراد به القلة النسبية؛ لأن الأبرار قليلون بالقياس إلى سائر البشر. أما الملائكة فكلهم بررة، فناسبهم جمع الكثرة. وقد ورد هذا التوجيه أيضًا في النقل عن «معاني الأبنية في العربية».","sources":[{"label":"السامرائي، على طريق التفسير البياني، ج1، ص224–227.","url":""}]},{"id":"s76-47","number":47,"surah":76,"verses":[13],"references":[{"surah":76,"verses":[13]}],"verseLabel":"الإنسان: 13","question":"ما فائدة تكرار ﴿فِيهَا﴾ في ﴿مُتَّكِئِينَ فِيهَا عَلَى الْأَرَائِكِ لَا يَرَوْنَ فِيهَا شَمْسًا وَلَا زَمْهَرِيرًا﴾؟","answer":"لئلا يُتوهم اختصاص انتفاء الشمس والزمهرير بحال الاتكاء على الأرائك؛ فهو وصف للجنة، سواء أكانوا متكئين أم في غير هذه الحال.","sources":[{"label":"https://islamiyyat.com/الإنسان/","url":""}]},{"id":"s78-34","number":34,"surah":78,"verses":[14,16],"references":[{"surah":78,"verses":[14,16]}],"verseLabel":"النبأ: 14، 16","question":"ما سر وصف الماء بـ﴿ثَجَّاجًا﴾ وتعداد ﴿حَبًّا وَنَبَاتًا وَجَنَّاتٍ أَلْفَافًا﴾، ولم يذكر مثل ذلك في طه؟","answer":"الثجّاج الشديد الانصباب، فلما زاد في وصف الماء زاد فيما يخرج من الأرض فذكر الحب والنبات والجنات الملتفة. أما في طه فلم يصف الماء وقال: ﴿فَأَخْرَجْنَا بِهِ أَزْوَاجًا مِنْ نَبَاتٍ شَتَّى﴾، فزاد في النبات وأنواعه لما زاد في الماء.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص103.","url":""}]},{"id":"s78-35","number":35,"surah":78,"verses":[19,20],"references":[{"surah":78,"verses":[19,20]}],"verseLabel":"النبأ: 19، 20","question":"ما دلالة «كان» والماضي في قوله: ﴿وَفُتِحَتِ السَّمَاءُ فَكَانَتْ أَبْوَابًا وَسُيِّرَتِ الْجِبَالُ فَكَانَتْ سَرَابًا﴾، وهل هي بمعنى «صار»؟","answer":"جعلها النحاة بمعنى «صار»، والأولى أنها ليست بمعناها؛ فالصيرورة قد تقتضي الزمن الطويل، و«كان» تطوي الزمن، فكأن هذا شأنها منذ الماضي وكأن حالتها الجديدة حاصلة قبل النظر والمشاهدة. وعبّر عن المستقبل بالماضي للدلالة على تحقق الوقوع.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج1، ص217–218؛ والجملة العربية والمعنى، ص217.","url":""}]},{"id":"s78-36","number":36,"surah":78,"verses":[28],"references":[{"surah":78,"verses":[28]}],"verseLabel":"النبأ: 28","question":"ما سر التعبير بالمصدر «كِذَّاب» في قوله: ﴿وَكَذَّبُوا بِآيَاتِنَا كِذَّابًا﴾، وقد قال في البروج: ﴿فِي تَكْذِيبٍ﴾؟","answer":"من معاني «الكِذّاب» الإفراط في التكذيب، وقد ذكر في النبأ من صفاتهم ما زاد على البروج: أنهم طاغون، وأنهم لا يرجون حسابًا، وأنهم كذّبوا بالآيات، فجاء بالمصدر الدال على المبالغة مفعولًا مطلقًا مؤكدًا لفعله. وفي «الكشاف» نحو هذا في معنى الإفراط.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص112–113.","url":""}]},{"id":"s78-37","number":37,"surah":78,"verses":[28],"references":[{"surah":78,"verses":[28]}],"verseLabel":"النبأ: 28","question":"ما سر مناسبة ﴿فِي تَكْذِيبٍ﴾ في البروج لسياقها، في مقابل ﴿كِذَّابًا﴾ هنا؟","answer":"لما قال في البروج ﴿بَلِ الَّذِينَ كَفَرُوا فِي تَكْذِيبٍ﴾ أي ساقطون فيه والتكذيب محيط بهم، ناسب أن يقول بعده: ﴿وَاللَّهُ مِنْ وَرَائِهِمْ مُحِيطٌ﴾، فالتكذيب محيط بهم والله محيط بالجميع. أما في النبأ فزاد التفصيل في كفرهم فأكّد الفعل بمصدر المبالغة.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص113.","url":""}]},{"id":"s78-38","number":38,"surah":78,"verses":[35],"references":[{"surah":78,"verses":[35]}],"verseLabel":"النبأ: 35","question":"ما سر قوله: ﴿لَا يَسْمَعُونَ فِيهَا لَغْوًا وَلَا كِذَّابًا﴾ دون «ولا تكذيبًا» أو «ولا كذبًا»؟","answer":"«الكِذّاب» يكون بمعنى الكذب وبمعنى التكذيب، فجمع المعنيين في تعبير واحد، أي: لا يسمعون فيها كذبًا ولا تكذيبًا، فنفى الأمرين معًا، وهو من لطيف التوسع في المعنى.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص113.","url":""}]},{"id":"s78-39","number":39,"surah":78,"verses":[40],"references":[{"surah":78,"verses":[40]}],"verseLabel":"النبأ: 40","question":"ما سر التوكيد بـ«إنّ» والتعبير بالماضي في قوله: ﴿إِنَّا أَنْذَرْنَاكُمْ عَذَابًا قَرِيبًا﴾، وقد قال في الليل: ﴿فَأَنْذَرْتُكُمْ نَارًا تَلَظَّى﴾ بلا توكيد؟","answer":"جاء بالماضي لأن الإنذار تمّ واكتمل، بخلاف ﴿إِنَّمَا أُنْذِرُكُمْ بِالْوَحْيِ﴾ لأن الوحي مستمر. وأكّده هنا دون الليل لأن الإنذار في الليل لم يرد إلا في موضع واحد، أما في النبأ فاتسع وتكرر في أول السورة ووسطها وآخرها، فناسب التوكيد.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص143–144.","url":""}]},{"id":"s79-37","number":37,"surah":79,"verses":[16,17],"references":[{"surah":79,"verses":[16,17]}],"verseLabel":"النازعات: 16، 17","question":"ما سر ترك «أن» المفسّرة في قوله: ﴿إِذْ نَادَاهُ رَبُّهُ بِالْوَادِ الْمُقَدَّسِ طُوًى اذْهَبْ﴾، وذكرها في آل عمران: ﴿يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا﴾؟","answer":"المقام في آل عمران أنهم سمعوا مناديًا فآمنوا وانتهى الأمر، أما في النازعات فمقام تكليف لموسى بدعوة الطاغية فرعون مع إخباره أنه بالواد المقدس، فهو أهم. والقول من الله مباشرةً أكرم وأهم من ذكر المضمون، فحذف «أن» في الأهم من المقامين وذكرها فيما هو أقل أهمية.","sources":[{"label":"فاضل السامرائي، الجملة العربية تأليفها وأقسامها، ص219–220.","url":""}]},{"id":"s79-38","number":38,"surah":79,"verses":[17,21],"references":[{"surah":79,"verses":[17,21]}],"verseLabel":"النازعات: 17، 21","question":"ما سر الانتقال من ﴿اذْهَبْ إِلَى فِرْعَوْنَ﴾ إلى ﴿فَأَرَاهُ الْآيَةَ الْكُبْرَى﴾ دون ذكر ذهاب موسى إليه؟","answer":"حُذف لأنه لا يتعلق غرض بذكره وهو مفهوم من السياق يدل عليه العقل، أي: فذهب فأراه. فانتقل رأسًا من تكليفه بالرسالة إلى موقف فرعون، وذكر ما هو محطّ الاهتمام: فحوى الرسالة وموقف فرعون وعاقبته ومآله، وهذا كثير في القصص القرآني.","sources":[{"label":"فاضل السامرائي، الجملة العربية تأليفها وأقسامها، ص81، ص100.","url":""}]},{"id":"s79-39","number":39,"surah":79,"verses":[18],"references":[{"surah":79,"verses":[18]}],"verseLabel":"النازعات: 18","question":"ما دلالة الاستفهام وتعديته بـ«إلى» في قوله: ﴿فَقُلْ هَلْ لَكَ إِلَى أَنْ تَزَكَّى﴾، والأصل «هل لك في كذا»؟","answer":"«هل» هنا للعرض. ولما كان هذا دعاءً من موسى ضُمِّن معنى الدعوة والإرشاد، فصار تقديره: أدعوك وأرشدك إلى أن تزكّى، فعُدّي بـ«إلى». وفي «الخصائص» و«البرهان» نحو هذا.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص240؛ والجملة العربية والمعنى، ص186.","url":""}]},{"id":"s79-40","number":40,"surah":79,"verses":[32],"references":[{"surah":79,"verses":[32]}],"verseLabel":"النازعات: 32","question":"ما سر التعبير بـ«الجبال» في قوله: ﴿وَالْجِبَالَ أَرْسَاهَا﴾ دون «الأطوار»؟","answer":"ذكر لفظ الجبال في مقام التهويل والتعظيم والدلالة على القدرة التي لا تُحدّ، ففيه من الدلالة على العِظَم ما ليس في اسم الطور، ونظيره ﴿وَالْجِبَالَ أَوْتَادًا﴾ في النبأ.","sources":[{"label":"فاضل السامرائي، الجملة العربية تأليفها وأقسامها، ص41؛ وبلاغة الكلمة في التعبير القرآني، ص111.","url":""}]},{"id":"s79-41","number":41,"surah":79,"verses":[35],"references":[{"surah":79,"verses":[35]}],"verseLabel":"النازعات: 35","question":"ما سر التعبير بـ«يتذكّر» في قوله: ﴿يَوْمَ يَتَذَكَّرُ الْإِنْسَانُ مَا سَعَى﴾ دون «يذّكّر»؟","answer":"استعمل «يتذكر» للتذكر العقلي ولما يحتاج إلى طول وقت، وهذا تذكّر لما عمله الإنسان في حياته كلها، فهو يستغرق وقتًا طويلًا، وليس تذكرًا قلبيًا يدفعه إلى عمل ينفعه. أما «يذّكّر» فلما فيه هزّة للقلب ومبالغة في التذكر.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص46–47.","url":""}]},{"id":"s80-25","number":25,"surah":80,"verses":[1,2],"references":[{"surah":80,"verses":[1,2]}],"verseLabel":"عبس: 1، 2","question":"ما سر التعبير بـ«أن» المصدرية في قوله: ﴿أَن جَاءَهُ الْأَعْمَى﴾؟","answer":"المعنى: عبس لمجيء الأعمى، و«أن» تدل على مجرد الحدث. ولو قيل: «لما جاءه» أو «بما جاءه» لكان المعنى أنه عبس للشيء الذي جاء به الأعمى، ولم يأتِ بشيء وإنما عبس لمجيئه. ولو قيل: «ما جاءه» لكان المعنى أنه عبس كلما جاءه، وكلا المعنيين غير مراد.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج3، ص160.","url":""}]},{"id":"s80-26","number":26,"surah":80,"verses":[3],"references":[{"surah":80,"verses":[3]}],"verseLabel":"عبس: 3","question":"ما سر الإدغام في ﴿يَزَّكَّى﴾ هنا، مع أنه قال في سورة الليل: ﴿يَتَزَكَّى﴾؟","answer":"التزكّي في الليل مقرون بإيتاء المال، وهو عمل طويل الأمد متدرّج، فجاء بالصيغة الأطول. أما هنا فالأعمى جاء يستفهم أو يسترشد في وقت من الأوقات فيزكو قلبه بذلك، ومدته أقصر، وهو مقرون بالخشية وطلب الذكر، والخشية أمر قلبي، فجاء بالصيغة المدغمة.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص44–45.","url":""}]},{"id":"s80-27","number":27,"surah":80,"verses":[16],"references":[{"surah":80,"verses":[16]}],"verseLabel":"عبس: 16","question":"ما سر وصف الملائكة بـ﴿بَرَرَةٍ﴾ في قوله: ﴿كِرَامٍ بَرَرَةٍ﴾، والمؤمنون يوصفون بالأبرار؟","answer":"لم يرد لفظ «البررة» إلا في هذا الموطن، وهو في صفة الملائكة. و«الأبرار» جمع قلة استُعمل لقلة نسبية، لأن الأبرار من بني آدم قلة إذا قيسوا بالفجار. أما الملائكة فكلهم بررة، فجيء لهم بجمع الكثرة.","sources":[{"label":"فاضل السامرائي، معاني الأبنية في العربية، ص125؛ وعلى طريق التفسير البياني، ج1، ص164.","url":""}]},{"id":"s80-28","number":28,"surah":80,"verses":[21,22],"references":[{"surah":80,"verses":[21,22]}],"verseLabel":"عبس: 21، 22","question":"ما سر العطف بالفاء في ﴿فَأَقْبَرَهُ﴾ وبـ«ثم» في ﴿ثُمَّ إِذَا شَاءَ أَنشَرَهُ﴾؟","answer":"جاء بالفاء في «أقبره» لأن دفن الميت يكون عقب موته مباشرة، وجاء بعده بـ«ثم» لأن النشور يتأخر عن الدفن ويتراخى عنه. وهذا التوجيه منقول عن «التصريح على التوضيح».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص200؛ ومعاني النحو، ج3، ص238.","url":""}]},{"id":"s80-29","number":29,"surah":80,"verses":[24,29],"references":[{"surah":80,"verses":[24,29]}],"verseLabel":"عبس: 24، 29","question":"ما سر تقديم العنب والزيتون على النخل في قوله: ﴿حَبًّا وَعِنَبًا وَقَضْبًا وَزَيْتُونًا وَنَخْلًا﴾؟","answer":"لم يتقدم العنب على النخل في القرآن إلا هنا وفي الرعد. والآيات هنا في الأطعمة: ﴿فَلْيَنظُرِ الْإِنسَانُ إِلَىٰ طَعَامِهِ﴾، والحب طعام والعنب والزيتون ثمر، أما النخل فاسم الشجرة، فقدّم الأطعمة وأخّر الشجر وجعل النخل بجنب الحدائق. ثم إنه رتّبها بحسب كثرتها في العالم: الحب، ثم العنب، ثم الزيتون، ثم النخل.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص122–123.","url":""}]},{"id":"s80-30","number":30,"surah":80,"verses":[25,29],"references":[{"surah":80,"verses":[25,29]}],"verseLabel":"عبس: 25، 29","question":"ما سر قوله: ﴿أَنَّا صَبَبْنَا الْمَاءَ صَبًّا﴾ و﴿نَخْلًا﴾ هنا، مع قوله في النحل: ﴿أَنزَلَ مِنَ السَّمَاءِ مَاءً﴾ و﴿النَّخِيلَ﴾؟","answer":"«النخل» في عبس أكثر من «النخيل» في النحل، ويدل عليه السياق: فالصبّ أكثر من الإنزال وقد أكّده بالمصدر، وخصّ الماء هنا بالطعام ولم يذكر الشراب، والمنتوجات المذكورة هنا أكثر. وأسند الأفعال إلى ضمير الجمع (صببنا، شققنا، فأنبتنا)، والإسناد إلى المتكلم يقتضي زيادة التفضل.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص99–100.","url":""}]},{"id":"s80-31","number":31,"surah":80,"verses":[34],"references":[{"surah":80,"verses":[34]}],"verseLabel":"عبس: 34","question":"ما سر التعبير بـ﴿الْمَرْءُ﴾ في ﴿يَوْمَ يَفِرُّ الْمَرْءُ﴾، وقد قال قبلها: ﴿قُتِلَ الْإِنسَانُ﴾ و﴿فَلْيَنظُرِ الْإِنسَانُ﴾؟","answer":"الأصل في «المرء» أن يُطلق على الرجل، وقد ذكر الفرار من الصاحبة، والفارّ منها هو الرجل، و«الإنسان» يشمل الذكر والأنثى. ثم إن مشهد الفرار يشمل رجال الثقلين من الإنس والجن، فـ«المرء» أخصّ من الإنسان من جهة وأعمّ منه من جهة، أما ما قبلها من الطعام فخاص بالإنسان.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص196–197.","url":""}]},{"id":"s80-32","number":32,"surah":80,"verses":[34,36],"references":[{"surah":80,"verses":[34,36]}],"verseLabel":"عبس: 34، 36","question":"ما مناسبة مشهد الفرار يوم القيامة لسورة عبس؟","answer":"السورة تبدأ بـ﴿عَبَسَ وَتَوَلَّى﴾، والتولّي نوع من الفرار والانصراف، والعبوس نوع من الفرار النفسي، والتلهّي في ﴿فَأَنتَ عَنْهُ تَلَهَّىٰ﴾ فرار بصورة ما. فوُضع مشهد الفرار الأكبر في السورة التي تبدأ بنوع من الفرار، كما وُضع مشهد العذاب في المعارج التي تبدأ بالعذاب.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص197.","url":""}]},{"id":"s80-33","number":33,"surah":80,"verses":[42],"references":[{"surah":80,"verses":[42]}],"verseLabel":"عبس: 42","question":"ما سر تقديم ﴿الْكَفَرَةُ﴾ على ﴿الْفَجَرَةُ﴾، وفي نوح: ﴿فَاجِرًا كَفَّارًا﴾؟","answer":"تقدّم التعجب من الكفر في ﴿قُتِلَ الْإِنسَانُ مَا أَكْفَرَهُ﴾. ووصف وجوههم بأن عليها غبرة ترهقها قترة، أي مغطاة بالغبار والسواد، والكفر في أصله التغطية والستر، فناسب ذلك. ثم إن المذكورين كفار، والفاجر قد يكون مؤمنًا منبعثًا في المعاصي، فبدأ بالكفر.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص136. المصادر","url":""}]},{"id":"s81-37","number":37,"surah":81,"verses":[15,16],"references":[{"surah":81,"verses":[15,16]}],"verseLabel":"التكوير: 15، 16","question":"ما دلالة بناء «فُعَّل» في قوله: ﴿فَلَا أُقْسِمُ بِالْخُنَّسِ الْجَوَارِ الْكُنَّسِ﴾؟","answer":"هذا الجمع قد يدل على التكثير، فالخُنَّس والكُنَّس هي التي تخنس وتختفي كثيرًا، لا مرة واحدة. ومن أبرز دلالات هذا البناء الحركة الظاهرة.","sources":[{"label":"فاضل السامرائي، معاني الأبنية في العربية، ص133، 135.","url":""}]},{"id":"s82-26","number":26,"surah":82,"verses":[1,4],"references":[{"surah":82,"verses":[1,4]}],"verseLabel":"الانفطار: 1، 4","question":"ما سر تقديم الاسم على الفعل بعد «إذا» في قوله: ﴿إِذَا السَّمَاءُ انفَطَرَتْ وَإِذَا الْكَوَاكِبُ انتَثَرَتْ﴾؟","answer":"التقديم هنا للتهويل، فانفطار السماء وانتثار الكواكب وتفجير البحار وبعثرة القبور لم يحدث شيء منها قط، وهذه الأجرام مستقرة على عادتها الدهور المتطاولة. بخلاف ﴿إِذَا زُلْزِلَتِ الْأَرْضُ﴾ فلم يقدّم الاسم، لأن الزلازل واقعة متكررة.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص103–104؛ وج2، ص53–54؛ والنحو العربي أحكام ومعان، ج1، ص370.","url":""}]},{"id":"s82-27","number":27,"surah":82,"verses":[6],"references":[{"surah":82,"verses":[6]}],"verseLabel":"الانفطار: 6","question":"ما سر ذكر حرف النداء «يا» في قوله: ﴿يَا أَيُّهَا الْإِنسَانُ مَا غَرَّكَ بِرَبِّكَ الْكَرِيمِ﴾؟","answer":"ذكر «يا» هنا للزيادة في التنبيه والزيادة في التقريع، وفيه من مدّ الصوت للإسماع ما ليس في النداء بحذفها، كقوله: ﴿إِن يَشَأْ يُذْهِبْكُمْ أَيُّهَا النَّاسُ﴾.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص325؛ والنحو العربي أحكام ومعان، ج2، ص337.","url":""}]},{"id":"s82-28","number":28,"surah":82,"verses":[6,7],"references":[{"surah":82,"verses":[6,7]}],"verseLabel":"الانفطار: 6، 7","question":"ما سر النداء بلفظ ﴿الْإِنسَانُ﴾ دون «البشر» في قوله: ﴿يَا أَيُّهَا الْإِنسَانُ مَا غَرَّكَ﴾؟","answer":"إذا أراد القرآن وصف الإنسان بصفات مما طُبع عليها، أو سؤاله للتبكيت والاتعاظ، أو نداءه لغرض ما، جاء بلفظ «الإنسان». وإنما يأتي بلفظ «البشر» لإثبات المماثلة وحيث يُعتبر من الإنسان جثّته وظاهره. وفي «مفردات الراغب» نحو هذا في معنى البشر.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص119–120.","url":""}]},{"id":"s83-37","number":37,"surah":83,"verses":[2],"references":[{"surah":83,"verses":[2]}],"verseLabel":"المطففين: 2","question":"ما سر تعدية الاكتيال بـ«على» في قوله: ﴿الَّذِينَ إِذَا اكْتَالُوا عَلَى النَّاسِ يَسْتَوْفُونَ﴾؟","answer":"قيل: «على» بمعنى «من»، والصواب أن الفعل متضمّن معنى التسلط والتحكم، أي تسلطوا على الناس بالاكتيال وظلموهم حقهم. فـ«اكتال منه» لا يفيد أنه ظلمه حقه، بخلاف «اكتال عليه» ففيه معنى الاستعلاء والجور، وهذا حال المطففين الذين يأخذون أكثر من حقهم. وفي «شرح الدماميني على المغني» نحو هذا.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص209؛ ومعاني النحو، ج3، ص51–52؛ والجملة العربية والمعنى، ص232.","url":""}]},{"id":"s83-38","number":38,"surah":83,"verses":[3],"references":[{"surah":83,"verses":[3]}],"verseLabel":"المطففين: 3","question":"ما سر حذف اللام في قوله: ﴿وَإِذَا كَالُوهُمْ أَو وَزَنُوهُمْ يُخْسِرُونَ﴾، ولم يقل: «كالوا لهم أو وزنوا لهم»؟","answer":"كلا التعبيرين جائز، لكن اللام تفيد الاستحقاق، وهؤلاء لم يُعطوا الناس حقهم، فحُذفت اللام الدالة على الاستحقاق إشارة إلى أنهم منعوهم حقوقهم. وهذا التوجيه حكاه عن غيره بقوله «قالوا» دون تسمية قائل.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص209؛ ومعاني النحو، ج3، ص52.","url":""}]},{"id":"s83-39","number":39,"surah":83,"verses":[29,34],"references":[{"surah":83,"verses":[29,34]}],"verseLabel":"المطففين: 29، 34","question":"ما سر وصفهم بالإجرام أولًا في ﴿إِنَّ الَّذِينَ أَجْرَمُوا﴾، ثم بالكفر في ﴿فَالْيَوْمَ الَّذِينَ آمَنُوا مِنَ الْكُفَّارِ يَضْحَكُونَ﴾؟","answer":"وصفهم أولًا بالإجرام لأنهم اعتدوا على حقوق غيرهم بالسخرية. ثم ذكر حكمهم فسمّاهم كفارًا، إذ وصفوا المؤمنين بالضلال، لئلا يُظن أنهم مجرمون ليسوا كفارًا. وذكر الفريقين على العموم، فالمؤمنون عامة يضحكون من الكفار عامة.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص115–116. المصادر","url":""}]},{"id":"s87-30","number":30,"surah":87,"verses":[8],"references":[{"surah":87,"verses":[8]}],"verseLabel":"الأعلى: 8","question":"ما دلالة مجيء ﴿وَنُيَسِّرُكَ لِلْيُسْرَى﴾ بغير السين، مع قوله في سورة الليل: ﴿فَسَنُيَسِّرُهُ لِلْيُسْرَى﴾؟","answer":"حُذفت السين مع الرسول صلى الله عليه وسلم لأن أمره ميسر على كل حال وعلى سبيل الدوام، لا يختص ذلك بوقت دون وقت، ولو قال: «سنيسرك» لكان وعدًا بالتيسير في الاستقبال دون الحال، وهو غير مراد.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص132.","url":""}]},{"id":"s89-42","number":42,"surah":89,"verses":[15],"references":[{"surah":89,"verses":[15]}],"verseLabel":"الفجر: 15","question":"ما سر التعبير بـ«أكرمه» في قوله: ﴿فَأَكْرَمَهُ وَنَعَّمَهُ﴾ دون «كرّمه»؟","answer":"«فعّل» يفيد التكثير والمبالغة غالبًا، فاستُعمل التكريم لما هو أبلغ وأدوم وأعم، أما الإكرام هنا فالمقصود به إكرامه بالمال، ومثله ﴿بَل لَّا تُكْرِمُونَ الْيَتِيمَ﴾.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص58–59.","url":""}]},{"id":"s90-33","number":33,"surah":90,"verses":[11],"references":[{"surah":90,"verses":[11]}],"verseLabel":"البلد: 11","question":"ما دلالة «لا» في قوله: ﴿فَلَا اقْتَحَمَ الْعَقَبَةَ﴾ دون «ما اقتحم» أو «لم يقتحم»؟","answer":"جمع التعبير معانيَ مرادةً معًا: المضي أي لم يقتحمها، والاستقبال أي لا يقتحمها ما دام على حاله، والدعاء عليه بألا يقتحمها، والاستفهام المراد به التوبيخ والحض أي: أفلا اقتحم. ولو قال «ما اقتحم» أو «لم يقتحم» لم يُفد إلا الإخبار عن الماضي.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص266–270.","url":""}]},{"id":"s90-34","number":34,"surah":90,"verses":[18,19],"references":[{"surah":90,"verses":[18,19]}],"verseLabel":"البلد: 18، 19","question":"ما سر التعبير بـ«الميمنة» و«المشأمة» دون «أصحاب اليمين» و«أصحاب الشمال»؟","answer":"جمع اللفظان معانيَ مرادةً معًا: جهة اليمين والشمال، وإيتاء الصحائف باليمين والشمال، واليُمن والشؤم على أنفسهم وغيرهم، ولو قال «أصحاب اليمين» لأعطى معنى واحدًا. وفيه تناسب لفظي ببناء «مَفْعَلة» في العمل والوصف والجزاء: مسغبة، مقربة، متربة، مرحمة.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص276–278.","url":""}]},{"id":"s90-35","number":35,"surah":90,"verses":[19],"references":[{"surah":90,"verses":[19]}],"verseLabel":"البلد: 19","question":"ما سر المجيء بضمير الفصل في قوله: ﴿هُمْ أَصْحَابُ الْمَشْأَمَةِ﴾ دون آية المؤمنين؟","answer":"المؤمنون المذكورون من أصحاب الميمنة لا على جهة القصر، فمن أصحاب الميمنة من لم يتواصَ بصبر ولا مرحمة، أما الذين كفروا فهم أصحاب المشأمة حصرًا ما بقوا على كفرهم، فجيء بالضمير لإفادة الحصر. وفي «روح المعاني» نحو هذا.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص278.","url":""}]},{"id":"s90-36","number":36,"surah":90,"verses":[20],"references":[{"surah":90,"verses":[20]}],"verseLabel":"البلد: 20","question":"ما سر الاكتفاء بـ﴿مُّؤْصَدَةٌ﴾ هنا دون زيادة ﴿فِي عَمَدٍ مُّمَدَّدَةٍ﴾ كما في سورة الهمزة، وما سر ذكر جزاء الكافرين دون المؤمنين؟","answer":"توسّع في الهمزة في صفات المعذّب فتوسّع في عذابه، وذاك جمع المال واستوثق من حفظه فاستُوثق من غلق النار عليه، وهذا أهلك المال، ولم يُذكر في البلد إلا الكفر. واقتُصر على جزاء الكافرين لأن ذكر الجحيم هو المناسب لخلق الإنسان في كبد، وفي «روح المعاني» نحو هذا.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص280–283.","url":""}]},{"id":"s91-19","number":19,"surah":91,"verses":[7,11],"references":[{"surah":91,"verses":[7,11]}],"verseLabel":"الشمس: 7، 11","question":"ما سر تقييد القسم بالنفس المكلفة في الشمس وتمثيل الجواب بثمود، مع إطلاقهما في سورة الليل؟","answer":"قيّد القسم في الشمس بـ﴿وَنَفْسٍ وَمَا سَوَّاهَا فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا﴾ أي بالنفوس العاقلة المكلفة، فكان الجواب ومثاله مقيدًا بأمر واحد هو قوم ثمود؛ وأطلق في الليل ﴿وَمَا خَلَقَ الذَّكَرَ وَالْأُنثَى﴾ فأطلق الجواب لكل من أعطى ومن بخل، فناسب بين القسم والجواب في الموضعين.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص127.","url":""}]},{"id":"s92-29","number":29,"surah":92,"verses":[4],"references":[{"surah":92,"verses":[4]}],"verseLabel":"الليل: 4","question":"ما سر القسم والتوكيد وإضافة السعي إلى المخاطبين في قوله: ﴿إِنَّ سَعْيَكُمْ لَشَتَّى﴾ مع أن اختلاف السعي أمر مشاهد؟","answer":"المُقسَم عليه ليس السعي المشاهد في التجارة والزراعة، بل ما بيّنه التفصيل بعده من عاقبة من أعطى واتقى ومن بخل واستغنى، وهذا ينكره أكثر الناس فاستحق القسم والتوكيد. وأضاف السعي إلى المكلفين ولم يقل «إن السعي» لئلا يدخل سعي غير المكلفين من الحيوان.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص126.","url":""}]},{"id":"s92-30","number":30,"surah":92,"verses":[5,6],"references":[{"surah":92,"verses":[5,6]}],"verseLabel":"الليل: 5، 6","question":"ما سر ترتيب الصفات في قوله: ﴿فَأَمَّا مَنْ أَعْطَى وَاتَّقَى وَصَدَّقَ بِالْحُسْنَى﴾؟","answer":"قدّم العطاء لأن جو السورة شائع فيه المال وإعطاؤه أو البخل به، ثم ترقّى من المفضول إلى الأفضل ومن الأخص إلى الأعمّ؛ فكل معطٍ في سبيل الله متقٍ، وكل متقٍ مصدّق بالحسنى. ورتّبها كذلك بحسب قربها من السعي؛ فالعطاء أظهر السعي، والاتقاء فيه سعي وترك، والتصديق اعتقاد قلبي.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص129–131.","url":""}]},{"id":"s92-31","number":31,"surah":92,"verses":[5,10],"references":[{"surah":92,"verses":[5,10]}],"verseLabel":"الليل: 5، 10","question":"ما سر إطلاق «أعطى» و«اتقى» وحذف موصوف «الحسنى» و«اليسرى» و«العسرى»؟","answer":"أطلق العطاء فلم يذكر معطًى ولا نوعًا ولا مقدارًا، والراجح أنه إعطاء المال لمقابلته بالبخل وذكر المال بعده، وأطلق الاتقاء ليشمل كل ما ينبغي اتقاؤه. والحسنى واليسرى والعسرى صفات حُذف موصوفها لقصد الإطلاق، فالتيسير لليسرى عام في كل خير في الدنيا والآخرة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص127–129، 131، 134.","url":""}]},{"id":"s92-32","number":32,"surah":92,"verses":[14],"references":[{"surah":92,"verses":[14]}],"verseLabel":"الليل: 14","question":"ما سر التعبير بالماضي وترك التوكيد وتنكير النار في قوله: ﴿فَأَنذَرْتُكُمْ نَارًا تَلَظَّى﴾؟","answer":"عبّر بالماضي لأنه أنذرهم بأمر واحد أخبرهم به فتمّ، بخلاف ﴿أُنذِرُكُم بِالْوَحْيِ﴾ لأن الوحي مستمر. ولم يؤكده كما أكده في النبأ لأن الإنذار في الليل لم يرد إلا هنا، وفي النبأ تكرر في أولها ووسطها وآخرها. ونكّر النار ليعلمنا أن النار بكل أقسامها تستحق الإنذار، ولو عرّفها لظُنّ أن التحذير واقع على نار بعينها.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص142–144.","url":""}]},{"id":"s93-24","number":24,"surah":93,"verses":[6,8],"references":[{"surah":93,"verses":[6,8]}],"verseLabel":"الضحى: 6، 8","question":"ما سر ترتيب النعم الثلاث: الإيواء ثم الهداية ثم الغنى؟","answer":"هو الترتيب الطبيعي في الحياة؛ فاليتيم من هو دون البلوغ، فإذا بلغ احتاج إلى الهدى لأن البلوغ مناط التكليف، وجمع المال ينبغي أن يكون مبنيًّا على الهداية الربانية. وكل نعمة منها مرتبطة بالقسم؛ فاليتم والضلال والعيلة ليل وظلمة، والإيواء والهدى والغنى نور.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص117–118.","url":""}]},{"id":"s93-25","number":25,"surah":93,"verses":[6,8],"references":[{"surah":93,"verses":[6,8]}],"verseLabel":"الضحى: 6، 8","question":"ما سر حذف المفعول في «فآوى» و«فهدى» و«فأغنى»؟","answer":"حُذف لظهور المراد ورعاية الفاصلة وسعة الكرم معًا؛ فلو قال «فآواك» لكان الإيواء منحصرًا به، والمراد أنه آواه وآوى به ولأجله خلقًا كثيرًا، وهداه وهدى به، وأغناه وأغنى به. والقول بسعة الكرم في «روح المعاني» نحوه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص117–118.","url":""}]},{"id":"s93-26","number":26,"surah":93,"verses":[9,11],"references":[{"surah":93,"verses":[9,11]}],"verseLabel":"الضحى: 9، 11","question":"ما سر ترتيب الوصايا الثلاث مع أنها لا تقابل النعم على النسق نفسه؟","answer":"هو الترتيب الأمثل؛ فاليتيم أولًا بإزاء اليتم، والسائل يشمل سائل العلم فيقابل الهداية، وسائل المال فيقابل الغنى، ثم التحديث بالنعمة بعدها لأن التحديث يكون بعد وقوعها، ولأن الداعية يتحلى بالخلق الحسن قبل أن يتصدى للدعوة. وفي «البحر المحيط» و«روح المعاني» توجيهات لهذا الترتيب.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص120–122.","url":""}]},{"id":"s98-18","number":18,"surah":98,"verses":[6,8],"references":[{"surah":98,"verses":[6,8]}],"verseLabel":"البينة: 6، 8","question":"ما سر ذكر «أبدًا» في خلود المؤمنين دون خلود الكافرين في سورة البينة؟","answer":"من خطّ التعبير القرآني أنه إذا بسط وفصّل في وصف أحد الفريقين أو جزائه ذكر «الأبد»، وإن أوجز لم يذكره. وفي البينة أوجز في الكافرين فلم يزد على أنهم في نار جهنم خالدين فيها وأنهم شر البرية، وتوسّع في المؤمنين فذكر جنات عدن تجري من تحتها الأنهار ورضا الله عنهم ورضاهم عنه، فزاد في وصف خلودهم: ﴿خَالِدِينَ فِيهَا أَبَدًا﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص104–105.","url":""}]},{"id":"s99-13","number":13,"surah":99,"verses":[7,8],"references":[{"surah":99,"verses":[7,8]}],"verseLabel":"الزلزلة: 7، 8","question":"ما دلالة قوله: ﴿يَرَهُ﴾ في ﴿فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ﴾ دون أن يقول «يُجزَ به» أو «يحاسَب عليه»؟","answer":"رؤية العمل لا تقتضي أن صاحبه سيجازى به، بل إنه سيراه، وقد يغفره له ربه ويستره عليه. فذكر ما هو أيسر وهو الرؤية، ولم يذكر ما هو أعظم كالحساب والجزاء؛ فإذا كان هذا هو الخبر فكيف النبأ؟ وفي ذكر «مثقال ذرة» دلالة على أن ما فوقه داخل في الرؤية من باب أولى.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص243؛ الجملة العربية والمعنى، ص62.","url":""}]},{"id":"s108-13","number":13,"surah":108,"verses":[1,3],"references":[{"surah":108,"verses":[1,3]}],"verseLabel":"الكوثر: 1، 3","question":"ما سر إسناد الإعطاء إلى الله تعالى وعدم إسناد البتر إليه في السورة؟","answer":"قال ﴿إِنَّا أَعْطَيْنَاكَ﴾ ولم يقل «وجعلنا شانئك هو الأبتر»، بل أسند البتر إلى الشانئ نفسه، فهو أبتر من غير جعل جاعل وذلك وصفه هو، وهذا أذمّ له وأقبح. وبهذا ارتبط آخر السورة بأولها: أعطى نبيه الكوثر، ومبغضه مقطوع من كل خير.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص96–97.","url":""}]},{"id":"s108-14","number":14,"surah":108,"verses":[1,3],"references":[{"surah":108,"verses":[1,3]}],"verseLabel":"الكوثر: 1، 3","question":"ما سر مناسبة سورة الكوثر لسورة الماعون قبلها؟","answer":"هي كالمقابلة لها: ففي مقابل البخل في الماعون ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾، وفي مقابل السهو عن الصلاة ﴿فَصَلِّْ﴾، وفي مقابل الرياء ﴿لِرَبِّكَ﴾، وفي مقابل منع الماعون ﴿وَانْحَرْ﴾. وفي مقابل التكذيب بالدين ذكر الكوثر، لأن من أشهر معانيه نهر في الجنة، وهذا يقتضي الإيمان بيوم الدين.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص75–76.","url":""}]},{"id":"s108-15","number":15,"surah":108,"verses":[2],"references":[{"surah":108,"verses":[2]}],"verseLabel":"الكوثر: 2","question":"ما سر الالتفات في ﴿فَصَلِّ لِرَبِّكَ﴾ بعد ﴿إِنَّا أَعْطَيْنَاكَ﴾، دون «فصلّ لنا»؟","answer":"أفاد أن الصلاة تكون للرب وحده لا للمعطي على الإطلاق، فالمعطي يستحق الشكر ولا يستحق الصلاة إلا الله، ورفع توهم أن «نا» ضمير اشتراك لا ضمير عظمة. واختيار «الرب» لما فيه من معنى التربية والعناية المناسب للعطاء، وإضافته إلى ضمير الخطاب تكريم. وفي «التفسير الكبير» نحو هذا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص86–87، 93.","url":""}]},{"id":"s108-16","number":16,"surah":108,"verses":[2],"references":[{"surah":108,"verses":[2]}],"verseLabel":"الكوثر: 2","question":"ما سر التعبير بـ﴿وَانْحَرْ﴾ دون «اذبح» أو «ضَحّ» أو «آتِ الزكاة»؟","answer":"النحر خاص بالإبل وهي أعزّ أموال العرب، فناسب العطاءَ الكثير أن يتصدق بالكثير شكرًا، والذبح والتضحية عامّان يجزئ فيهما الشاة. والضحية مختصة بأيام الأضحى والنحر مطلق. ولو قال «وآتِ الزكاة» لما اختلف عن أمر عامة المسلمين فلا يكون شكرًا خاصًّا على الكوثر. وفي «التفسير الكبير» نحو هذا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص88–90.","url":""}]},{"id":"s108-17","number":17,"surah":108,"verses":[3],"references":[{"surah":108,"verses":[3]}],"verseLabel":"الكوثر: 3","question":"ما سر التعبير بـ«الأبتر» دون «المبتور»، وبـ«شانئ» في قراءة الجمهور؟","answer":"«الأبتر» صفة دالة على الثبوت كالأسمر والأعمى، بخلاف «المبتور» الدال على الحدوث. وقراءة الجمهور «شانئك» أولى من «شَنِئك»؛ لأن «شَنِئ» صيغة مبالغة تجعل البتر للمبالغ في البغض، أما «شانئك» فيدل على أن المبغض أبتر مهما قلّ بغضه أو كثر.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص95.","url":""}]},{"id":"s111-14","number":14,"surah":111,"verses":[1,2],"references":[{"surah":111,"verses":[1,2]}],"verseLabel":"المسد: 1، 2","question":"ما سر اقتران ذكر الكسب بذكر اليدين في قوله تعالى: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ * مَا أَغْنَىٰ عَنْهُ مَالُهُ وَمَا كَسَبَ﴾؟","answer":"الأيدي آلة الكسب، ولذلك كثيرًا ما يقترن الكسب بالأيدي في القرآن، كقوله: ﴿بِمَا كَسَبَتْ أَيْدِي النَّاسِ﴾ و﴿فَبِمَا كَسَبَتْ أَيْدِيكُمْ﴾؛ فلما ذكر يدَي أبي لهب ذكر ما كسب.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية، ج2، ص96.","url":""}]},{"id":"s112-15","number":15,"surah":112,"verses":[2],"references":[{"surah":112,"verses":[2]}],"verseLabel":"الإخلاص: 2","question":"ما سر التعبير بـ«الصمد» دون «المقصود» أو «الملتجَأ إليه»؟","answer":"«الصمد» له أكثر من معنى من معاني الكمال: المصمود إليه في الحوائج، والسيد الذي انتهى سؤدده، والذي لا جوف له، والدائم الباقي بعد فناء خلقه، وهو الصمد بكل هذه المعاني. و«المقصود» معنى واحد من معانيه، ولم يقيّد الصمدية بشيء فهو المقصود على الإطلاق.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص63–65.","url":""}]},{"id":"s113-15","number":15,"surah":113,"verses":[1],"references":[{"surah":113,"verses":[1]}],"verseLabel":"الفلق: 1","question":"ما سر اختيار «الفلق» دون «الصبح»، وما دلالة تخصيصه بالذكر في الاستعاذة؟","answer":"الفلق مشعر بتبدد ظلمة الليل ومجيء الفرج، والقادر على إزالة الظلمة عن العالم قادر أن يدفع عن العائذ ما يخافه، وفي «التفسير الكبير» وتفسير البيضاوي نحو هذا. ولفظ «الفلق» مشعر بالتغير والحركة لأنه انشقاق الضوء عن الظلمة، أما «الصبح» فيفيد تعيين الوقت، والفلق أعمّ معنى إذ يشمل كل ما يفلقه الله. وناسب ذكرُه ذكرَ «الغاسق» بعده.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص30–32.","url":""}]},{"id":"s113-16","number":16,"surah":113,"verses":[1],"references":[{"surah":113,"verses":[1]}],"verseLabel":"الفلق: 1","question":"ما سر قوله: «أعوذ» من غير توكيد، مع قوله في مواطن أخرى: ﴿وَإِنِّي عُذْتُ بِرَبِّي وَرَبِّكُم﴾؟","answer":"الاستعاذة تكون على قدر ما يحذره المستعيذ؛ فإذا كان المحذور شديدًا متسلطًا يتهدده هو على الخصوص أكّدها، كاستعاذة موسى حين هدده فرعون بالقتل، وإلا قال «أعوذ». وما في المعوذتين ليس من هذا النوع من التهديد المخصوص، فلم يحتج إلى توكيد.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص26–28.","url":""}]},{"id":"s113-17","number":17,"surah":113,"verses":[2],"references":[{"surah":113,"verses":[2]}],"verseLabel":"الفلق: 2","question":"ما سر التعبير بـ«ما» في ﴿مِن شَرِّ مَا خَلَقَ﴾ دون «مَن» أو «الذي»؟","answer":"ليتناول كل شرّ من العاقل وغيره، وغلّب غير العاقل لأن الأصل ألا يصدر شرّ من عاقل، وفي «التفسير الكبير» نحو هذا. و«ما» أعمّ من «الذي» و«التي» و«الذين» و«اللاتي»، لأنها تكون للمفرد والمثنى والجمع المذكر والمؤنث، فكانت أولى من غيرها على كل وجه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص33–34.","url":""}]},{"id":"s113-18","number":18,"surah":113,"verses":[2,5],"references":[{"surah":113,"verses":[2,5]}],"verseLabel":"الفلق: 2، 5","question":"ما سر ترتيب المستعاذ منه في السورة، وتنكير «غاسق» و«حاسد» وتعريف «النفاثات»؟","answer":"تدرّج من العام إلى الخاص ومن الكثرة إلى القلة: فبدأ بشر ما خلق، ثم الغاسق الذي يدخل كل يوم، ثم النفاثات وهن كثير وشرهن متعدد، ثم الحاسد وشره مخصوص بالحسد. وخصّ هؤلاء بعد التعميم لخفاء شرهم، وهذا منقول عن «الكشاف». ونكّر الغاسق والحاسد لأنه ليس كل غاسق يكون فيه الشر ولا كل حاسد يكون منه الضرر، وعرّف النفاثات لأن كل نفاثة شريرة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص41–42.","url":""}]},{"id":"s113-19","number":19,"surah":113,"verses":[2,5],"references":[{"surah":113,"verses":[2,5]}],"verseLabel":"الفلق: 2، 5","question":"ما سر تكرير «مِن شَرّ» مع كل مستعاذ منه؟","answer":"للدلالة على أن كلًّا من المذكورين تنبغي الاستعاذة منه على وجه الاستقلال لعظم شره. ولو قال «من شر ما خلق وغاسق والنفاثات» لاحتمل الاستعاذة من شرها إذا اجتمعت لا إذا انفردت، أو الاستعاذة من ذواتها لا من شرورها، وذكر «من» مع كل واحد أدلّ على استقلال كل صنف وآكد.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص38–39.","url":""}]},{"id":"s113-20","number":20,"surah":113,"verses":[4],"references":[{"surah":113,"verses":[4]}],"verseLabel":"الفلق: 4","question":"ما سر التعبير بـ«النفاثات» صفةً بلا موصوف، وبجمع الإناث، وبصيغة المبالغة؟","answer":"لم يذكر الموصوف لإرادة العموم، وجاء بجمع الإناث لأنه يشمل النفوس والأرواح والجماعات والنساء، ولو قال «النفاثين» لم يشمل إلا الذكور. ولما جمع «العُقَد» جمع كثرة جاء بصيغة المبالغة «نفّاثات» لأنه لما كثرت العقد كثر النفث، نظير «عالم الغيب» و«علّام الغيوب».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص37–38.","url":""}]},{"id":"s113-21","number":21,"surah":113,"verses":[5],"references":[{"surah":113,"verses":[5]}],"verseLabel":"الفلق: 5","question":"ما سر التعبير بـ«حاسد» دون «حسود»، وتقييده وتقييد الغاسق بـ«إذا» دون النفاثات؟","answer":"«حاسد» أعمّ لأنه يشمل المبالغ وغير المبالغ، والحسود إذا حسد كان حاسدًا في حينه. وقيّد الغاسق والحاسد بـ«إذا» لأن شرّ الغاسق يكون إذا دخل، والحاسد لا يؤثر إلا إذا أظهر حسده وعمل بمقتضاه، بخلاف شر النفاثات فهو مطلق غير مقيّد. وفي «البحر المحيط» و«روح المعاني» نحو هذا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص37–38، 43.","url":""}]},{"id":"s114-14","number":14,"surah":114,"verses":[1,3],"references":[{"surah":114,"verses":[1,3]}],"verseLabel":"الناس: 1، 3","question":"ما سر ترك العطف بالواو بين الصفات، وتكرير لفظ «الناس» دون الضمير؟","answer":"لم يعطف لئلا يُظنّ أنها ذوات متعددة، فهو الرب والملك والإله، وفي «التفسير القيم» نحو هذا. وكرر «الناس» لأن اللفظ يطلق على القليل والكثير: فناس المربي أقلّ، وناس الملك أكثر، وناس الإله يشملون الجميع؛ فلو قال «رب الناس وملكهم وإلههم» لظُنّ أنه ملك أولئك وحدهم وإلههم فحسب.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص46–49.","url":""}]},{"id":"s114-15","number":15,"surah":114,"verses":[1,4],"references":[{"surah":114,"verses":[1,4]}],"verseLabel":"الناس: 1، 4","question":"ما سر الاستعاذة بثلاث صفات من شرّ واحد في الناس، مع الاستعاذة بصفة واحدة من شرور متعددة في الفلق؟","answer":"شرّ الوسواس أخطر على الفرد والمجتمع من تلك الشرور، لأنه يعود على من ألقيت إليه الوسوسة وعلى غيره فيقع تحت طائلة الحساب في الدنيا والآخرة. ومضرة الدين أعظم من مضرة الدنيا فجاءت الاستعاذة منها بصفات ثلاث، وفي «البحر المحيط» نحو هذا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص45.","url":""}]},{"id":"s114-16","number":16,"surah":114,"verses":[1,6],"references":[{"surah":114,"verses":[1,6]}],"verseLabel":"الناس: 1، 6","question":"ما سر قوله: ﴿بِرَبِّ النَّاسِ﴾ دون «برب الجنة والناس» مع أن الوسواس من الفريقين؟","answer":"ذكر الوسوسة في صدور الناس لا في صدور الجنة، فالمعدوّ عليهم هم الناس، فاستعاذوا بربهم وملكهم وإلههم ليحميهم من هذا العدوان، كما يستغيث الموالي بسيدهم ووالي أمرهم. وفي «الكشاف» نحو هذا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص54.","url":""}]},{"id":"s114-17","number":17,"surah":114,"verses":[6],"references":[{"surah":114,"verses":[6]}],"verseLabel":"الناس: 6","question":"ما سر التعبير بـ«الجِنَّة» في مقابل «الناس»، وتقديمها في ﴿مِنَ الْجِنَّةِ وَالنَّاسِ﴾؟","answer":"الجن يقابل الإنس وهما الأصلان للجنسين، أما «الجنة» فمجموعة من الجن أو أفراد منهم فقابلت «الناس» الذين هم مجموعة قليلة أو كثيرة من الإنس. وقدّم الجنة لأنهم المعتدون على الناس والأصل في الوسوسة، وقد تكون وسوسة الإنسي بسبب وسوسة الشيطان؛ أما تقديم شياطين الإنس في الأنعام فلأن السياق هناك في كفرة الإنس.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص55–57. المصادر","url":""}]}]);
